package org.eclipse.rdf4j.common.webapp.system;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.common.app.AppConfiguration;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.web.servlet.ModelAndView;

class SystemInformationSecurityTest {

	@Test
	void controllersExposeOnlyApprovedSystemInformation() throws Exception {
		assertApprovedModel(modelFrom(new SystemInfoController()));
		assertApprovedModel(modelFrom(new SystemOverviewController()));
	}

	@Test
	void systemPagesOmitDiagnosticsAndEscapeRetainedValues() throws Exception {
		for (Path jsp : systemOverviewPages()) {
			String source = Files.readString(jsp);

			assertThat(source)
					.doesNotContain("system.overview.application.datadir")
					.doesNotContain("system.overview.runtime.user")
					.doesNotContain("system.info.javaprops")
					.doesNotContain("system.info.envvars")
					.doesNotContain("${appConfig.dataDir}")
					.doesNotContain("${server.user}")
					.contains("<c:out value=\"${appConfig.longName}\"")
					.contains("<c:out value=\"${appConfig.version}\"")
					.contains("<c:out value=\"${server.os}\"")
					.contains("<c:out value=\"${server.java}\"");
		}
	}

	@Test
	void legacyPublicControllerTypesRemainUsable() {
		SystemInfoController.ServerInfo infoServer = new SystemInfoController.ServerInfo();
		SystemInfoController.MemoryInfo infoMemory = new SystemInfoController.MemoryInfo();
		SystemOverviewController.ServerInfo overviewServer = new SystemOverviewController.ServerInfo();
		SystemOverviewController.MemoryInfo overviewMemory = new SystemOverviewController.MemoryInfo();

		assertThat(infoServer.getOs()).isNotBlank();
		assertThat(infoServer.getJava()).isNotBlank();
		assertThat(infoServer.getUser()).isNotNull();
		assertThat(infoMemory.getMaximum()).isPositive();
		assertThat(infoMemory.getUsed()).isNotNegative();
		assertThat(infoMemory.getPercentageInUse()).isBetween(0.0f, 1.0f);
		assertThat(overviewServer.getOs()).isNotBlank();
		assertThat(overviewServer.getJava()).isNotBlank();
		assertThat(overviewServer.getUser()).isNotNull();
		assertThat(overviewMemory.getMaximum()).isPositive();
		assertThat(overviewMemory.getUsed()).isNotNegative();
		assertThat(overviewMemory.getPercentageInUse()).isBetween(0.0f, 1.0f);
	}

	@Test
	void unconfiguredControllersRetainNullApplicationModel() throws Exception {
		assertThat(new SystemInfoController()
				.handleRequest(new MockHttpServletRequest(), new MockHttpServletResponse())
				.getModel()
				.get("appConfig")).isNull();
		assertThat(new SystemOverviewController()
				.handleRequest(new MockHttpServletRequest(), new MockHttpServletResponse())
				.getModel()
				.get("appConfig")).isNull();
	}

	private static ModelAndView modelFrom(SystemInfoController controller) throws Exception {
		controller.setConfig(mock(AppConfiguration.class));
		return controller.handleRequest(new MockHttpServletRequest(), new MockHttpServletResponse());
	}

	private static ModelAndView modelFrom(SystemOverviewController controller) throws Exception {
		controller.setConfig(mock(AppConfiguration.class));
		return controller.handleRequest(new MockHttpServletRequest(), new MockHttpServletResponse());
	}

	private static void assertApprovedModel(ModelAndView modelAndView) {
		Map<String, Object> model = modelAndView.getModel();
		assertThat(model).containsOnlyKeys("appConfig", "server", "memory");
		assertThat(beanProperties(model.get("appConfig"))).containsExactlyInAnyOrder("longName", "version");
		assertThat(beanProperties(model.get("server"))).containsExactlyInAnyOrder("java", "os");
		assertThat(beanProperties(model.get("memory")))
				.containsExactlyInAnyOrder("maximum", "percentageInUse", "used");
	}

	private static Set<String> beanProperties(Object value) {
		return Arrays.stream(value.getClass().getMethods())
				.filter(method -> method.getParameterCount() == 0)
				.map(Method::getName)
				.filter(name -> name.startsWith("get") && !name.equals("getClass"))
				.map(name -> Character.toLowerCase(name.charAt(3)) + name.substring(4))
				.collect(Collectors.toSet());
	}

	private static Set<Path> systemOverviewPages() {
		Path views = Path.of("..", "server", "src", "main", "webapp", "WEB-INF", "views", "system");
		return Set.of(views.resolve("overview.jsp"), views.resolve("info").resolve("overview.jsp"));
	}
}
